properties.query:
let rdp_events = SecurityEvent | where EventID == 4624 and LogonType == 10 | summarize rdp_time=min(TimeGenerated), rdp_src=any(SourceIP) by TargetUserName, Computer;
let cred_events = SecurityEvent | where EventID in (4688, 4663) and ProcessName has_any ("mimikatz", "procdump", "lsass") | summarize cred_time=min(TimeGenerated) by TargetUserName, Computer;
rdp_events | join kind=inner cred_events on TargetUserName, Computer | where cred_time - rdp_time between (0min .. 60min)
